// Layout is presentation only. IDs, connectivity and game position come from the
// engine; resizing and changing camera never change routes or available moves.
export function tabletopLayout(board,maxColumns=4,campClearance=0){
  const starts=board.starts.map(id=>board.locations.find(node=>node.id===id)).filter(Boolean),seen=new Set(starts.map(node=>node.id)),queue=[...starts],ordered=[];
  for(let index=0;index<queue.length;index++){
    const node=queue[index];
    for(const id of board.edges.flatMap(([a,b])=>a===node.id?[b]:b===node.id?[a]:[]).sort())if(!seen.has(id)){seen.add(id);const next=board.locations.find(item=>item.id===id);if(next){ordered.push(next);queue.push(next);}}
  }
  board.locations.forEach(node=>{if(!seen.has(node.id))ordered.push(node);});
  const columns=Math.min(ordered.length<=6?3:4,Math.max(2,maxColumns)),rows=Math.ceil(ordered.length/columns),compact=columns===2,positions={},projects={};
  const groups=Object.fromEntries(starts.map(node=>[node.id,board.projects.filter(project=>buildSite(board,project)===node.id)])),mostProjects=Math.max(1,...Object.values(groups).map(items=>items.length));
  const firstRow=218+mostProjects*82+(compact?campClearance:0),height=compact?firstRow+(rows-1)*132+100:620+Math.max(0,rows-2)*150;
  starts.forEach((node,index)=>{positions[node.id]={x:(index+.5)/starts.length,y:compact?95/height:.12,number:board.locations.indexOf(node)+1};});
  ordered.forEach((node,index)=>{const row=Math.floor(index/columns),count=Math.min(columns,ordered.length-row*columns),column=row%2?count-1-index%columns:index%columns;positions[node.id]={x:(column+.5)/count,y:compact?(firstRow+row*132)/height:rows===1?.67:.46+row*.40/(rows-1),number:board.locations.indexOf(node)+1};});
  for(const [site,items] of Object.entries(groups))items.forEach((project,index)=>{projects[project.id]={x:positions[site].x+(compact?0:(index-(items.length-1)/2)*(items.length===3?.15:.16)),y:compact?(190+campClearance+index*82)/height:.29};});
  return {positions,projects,starts:starts.map(node=>node.id),columns,rows,height};
}

