const routeKey=(a,b)=>[a,b].sort().join(':');
// Reconstruct from confirmed turn history so a reload retains the last journey.
// A preview or a mere selection must never create a travelled trail.
function lastPartyRoute(board,run,position){
  if(!run||!Number.isInteger(run.turn)||derive(board,run).position!==position)return [];
  for(let turn=Math.min(run.turn,MAX_TURNS-1);turn>=0;turn--){
    const step=run.steps?.['t'+turn];
    if(!step||!['answer','review'].includes(step.phase)||!board.locations.some(node=>node.id===step.targetId))continue;
    const path=routeForStep(board,run,turn);
    if(path?.length>1)return path;
  }
  return [];
}
// A rewind frame identifies its own simulated move explicitly. Never fall back
// to earlier live travel when showing the starting board or a construction.
function projectedPartyRoute(board,run,position,turn){
  if(!run||!Number.isInteger(turn)||turn<0||turn>=MAX_TURNS||turn!==run.turn-Number(stepOf(run).phase==='choose')||derive(board,run).position!==position)return [];
  const path=routeForStep(board,run,turn);
  return path?.length>1&&path[path.length-1]===position?path:[];
}
// Move markers stay on their edge, preferring gaps between tiles so even a
// long shortcut's label does not get buried underneath an unrelated location.
const routeStepPoint=(positions,a,b)=>[.5,.65,.35,.25,.75,.15,.85].map(fraction=>({x:a.x+(b.x-a.x)*fraction,y:a.y+(b.y-a.y)*fraction})).find(point=>Object.values(positions).every(tile=>Math.abs(point.x-tile.x)>.14||Math.abs(point.y-tile.y)>.105))||{x:(a.x+b.x)/2,y:(a.y+b.y)/2};
