        {board.projects.map((item,index)=>{const siteId=scene.projectSites[item.id],built=progress.built.includes(item.id);return <div className="lb-spatial-sites" data-build-site={siteId} style={{left:layout.projects[item.id].x*100+'%',top:layout.projects[item.id].y*100+'%'}} key={item.id}><button key={item.id} type="button" className="lb-spatial-project" data-map-construction={item.id} data-built={built} data-ready={ready.includes(item.id)} data-construction-state={projectState(item)} data-commission-project={commissionAt(item.id)} aria-pressed={selected===item.id} aria-label={projectLabel(item)+'. '+projectStatus(item)+(assignmentLabel(item.id)?'. '+assignmentLabel(item.id):'')+(plannedStep(item.id)?'. '+plannedLabel(item.id):'')+(earnedLabel(item.id)?'. '+earnedLabel(item.id):'')+(commissionAt(item.id)?'. '+commissionLabel+'. '+commissionDescription:'')} onClick={()=>inspect(item.id)}><AssignmentPriorityToken priority={assignmentPriority(item.id)}/>{plannedStep(item.id)&&<span className="lb-spatial-plan-pin" data-plan-pin={plannedStep(item.id)} aria-hidden="true">{plannedStep(item.id)}</span>}{commissionAt(item.id)&&<CommissionMarker projectId={item.id} theme={board.theme}/>} {symbol(item)}<ProductionCounter board={board} impact={impacts?.projects[item.id]} scope={impactScope} t={t}/><span className="lb-project-material" data-project-material={projectState(item)} aria-hidden="true"><i/><i/><i/></span><span className="lb-spatial-project-code">{String.fromCharCode(65+index)}{built?' ✓':''}{built&&(progress.usedProjects||[]).includes(item.id)&&<span className="lb-project-used" aria-label={tr(t,'tabletop_project_used','Used on this expedition')}>◆</span>}</span></button></div>;})}
